    private void btmAcceptActionPerformed(java.awt.event.ActionEvent evt) {//GEN-FIRST:event_btmAcceptActionPerformed
        // TODO add your handling code here:
        String userName = txtUser.getText();
        String password = passPassword.getText();
        User user = new User(userName, password, userName);
        
        UserController.validateLogin(user);
        
        if(UserController.validateLogin(user)){
            FrmContactsMenu frmContactsMenu = new FrmContactsMenu();
            frmContactsMenu.setVisible(true);
            lblErrorMessage.setForeground(Color.black);
            lblErrorMessage.setText("Welcome");
            this.setVisible(false);
            
        }else{
            lblErrorMessage.setForeground(Color.red);
            lblErrorMessage.setText("Either username or password is wrong");
        }
    }//GEN-LAST:event_btmAcceptActionPerformed

